'use strict';
// Ganguli's war books, checked against the public-domain text (Gutenberg 15475/15476).
// A repeated name can describe different deployments; references remain occurrence-specific.
const formationPassage=(book,section,file)=>({source:`${book} Parva · Ganguli §${section}`,url:`https://www.ibiblio.org/sripedia/ebooks/mb/m${file.slice(0,2)}/m${file}.htm`});
const formationUse=(side,book,section,file,text)=>({side,...formationPassage(book,section,file),text});
const commonArray=formationPassage('Drona','LXXXVII','07083');
FORMATIONS[0].sides=['Kaurava'];
FORMATIONS[1].sides=['Kaurava'];
FORMATIONS[1].uses=[formationUse('Kaurava','Drona','XX','07020','Drona later uses Garuda with himself at the mouth, Duryodhana at the head, Kripa and Kritavarman at the eyes, and Karna at the tail. The original diagram above refers to Bhishma’s earlier deployment.')];
FORMATIONS[2].sides=['Pandava','Kaurava'];
FORMATIONS[2].uses=[formationUse('Pandava','Bhishma','L–LI','06050','Dhrishtadyumna arranges Krauncharuma (called Krauncha in the next section), with Arjuna in advance, Drupada at the head and Kuntibhoja and Shaivya at the eyes.'),formationUse('Kaurava','Bhishma','LXXV','06075','Bhishma counters the Pandava Makara with a crane array: Drona at its beak, Ashvatthama and Kripa at its eyes, and Kritavarman among those in its head. The same formation name belongs to both armies.')];
FORMATIONS[3].sides=['Kaurava'];
FORMATIONS.push(
{id:'ardhachandra',name:'Ardhachandra-vyuha',sa:'अर्धचन्द्रव्यूह',shape:'Half-moon array',diagram:'crescent',sides:['Pandava','Kaurava'],...formationPassage('Bhishma','LVI','06056'),text:'Arjuna, aided by Dhrishtadyumna, arranges the Pandavas in a half-moon opposite Bhishma’s Garuda. Bhima stands on the right horn and Arjuna with Krishna on the left.',points:['Dhrishtadyumna, Shikhandin and the Panchalas occupy the middle.','The half-moon is not exclusive to the Pandavas; the Samsaptakas also use it.'],lesson:'Modern analogy: keep separated responsibilities connected through a shared centre.',uses:[formationUse('Kaurava','Drona','XVIII','07018','The Samsaptakas, fighting on Duryodhana’s side, form a half-moon with their chariots on a level field to face Arjuna.'),formationUse('Pandava','Drona','XX','07020','Yudhishthira forms a semicircular counter-array against Drona’s Garuda.'),formationUse('Pandava','Karna','11','08011','Arjuna counters Karna’s Makara with a half-moon. Bhima is on the left, Dhrishtadyumna on the right, Yudhishthira and Arjuna in the middle, and the twins behind the king. These positions differ from Bhishma §LVI.')]},
{id:'makara',name:'Makara-vyuha',sa:'मकरव्यूह',shape:'Aquatic-creature array',diagram:'makara',sides:['Pandava','Kaurava'],...formationPassage('Bhishma','LXXV','06075'),text:'At Yudhishthira’s instruction, Dhrishtadyumna arranges the Pandavas as a Makara. Drupada and Arjuna form its head, Nakula and Sahadeva its eyes, and Bhima its beak.',points:['Yudhishthira, Abhimanyu, Ghatotkacha and Satyaki are among those at the neck.','Virata, supported by Dhrishtadyumna, occupies the back; Shikhandin and Iravat are at the tail.','Makara denotes an aquatic creature; “crocodile” is a common simplified rendering.'],lesson:'Modern analogy: establish how the leading effort, supporting teams and rear support depend on one another.',uses:[formationUse('Kaurava','Bhishma','LXIX','06069','Bhishma protects a Makara array opposite the Pandavas’ Syena.'),formationUse('Kaurava','Karna','11','08011','Karna stands at the beak; Shakuni and Uluka at the eyes; Ashvatthama at the head; Duryodhana in the middle. Kritavarman and Kripa occupy the front feet, Shalya and Sushena the hind feet, and Chitra and Chitrasena the tail.')]},
{id:'syena',name:'Shyena-vyuha',sa:'श्येनव्यूह',shape:'Hawk-shaped array',diagram:'hawk',sides:['Pandava'],...formationPassage('Bhishma','LXIX','06069'),text:'The Pandavas form the Syena (Shyena, or hawk) against Bhishma’s Makara. Bhima takes the beak, Shikhandin and Dhrishtadyumna the eyes, Satyaki the head and Arjuna the neck.',points:['Drupada and his force occupy the left wing; the Kekaya king and his force the right.','Abhimanyu and Draupadi’s sons stand at the back; Yudhishthira and the twins are at the tail.','Shyena and Garuda are separate names in the narrative, despite the shared bird imagery.'],lesson:'Modern analogy: complementary roles matter more than giving everyone the same task.'},
{id:'vajra',name:'Vajra-vyuha',sa:'वज्रव्यूह',shape:'The immovable array',diagram:'wedge',sides:['Pandava'],...formationPassage('Bhishma','XIX','06019'),text:'After Yudhishthira proposes a needle-mouthed formation for a smaller force, Arjuna chooses the immovable array called Vajra. Bhima leads; Arjuna protects the formation.',points:['The array is described as facing all sides.','Vajra evokes Indra’s thunderbolt. The diagram is a teaching symbol, not a measured plan.','The proposed needle and the chosen Vajra should not be confused.'],lesson:'Modern analogy: select a plan for the situation rather than accepting the first suggestion.',uses:[formationUse('Pandava','Bhishma','LXXXII','06082','Yudhishthira also arranges a Vajra counter-array against Bhishma’s Mandala.')]},
{id:'mandala',name:'Mandala-vyuha',sa:'मण्डलव्यूह',shape:'Circular disposition',diagram:'circle',sides:['Kaurava'],...formationPassage('Bhishma','LXXXII','06082'),text:'Bhishma arrays the Kauravas in Mandala. The passage describes coordinated groupings of elephants, chariots, cavalry, archers and shield-bearing foot soldiers.',points:['The array advances facing west in this episode.','Yudhishthira responds with Vajra.','Mandala is a separate named occurrence from Drona’s circular array faced by Abhimanyu.'],lesson:'Modern analogy: coordination between different skills is as important as the leading role.'},
{id:'sringataka',name:'Shringataka-vyuha',sa:'शृङ्गाटकव्यूह',shape:'Horned array',diagram:'horns',sides:['Pandava'],...formationPassage('Bhishma','LXXXVIII','06088'),text:'Dhrishtadyumna forms Sringataka to counter the Kaurava army described as ocean-like. Bhima and Satyaki stand at its horns, with Arjuna next to them.',points:['Yudhishthira and the twins are in the centre.','Abhimanyu, Virata, Draupadi’s sons and Ghatotkacha guard the rear.','The horned outline is illustrative; the passage does not provide a scaled geometry.'],lesson:'Modern analogy: a strong forward effort also needs a protected centre and reliable support.'},
{id:'sarvatobhadra',name:'Sarvatobhadra-vyuha',sa:'सर्वतोभद्रव्यूह',shape:'All-sided array',diagram:'square',sides:['Kaurava'],...formationPassage('Bhishma','C','06100'),text:'Bhishma arranges Sarvatobhadra. He and several leaders hold the front; Drona, Bhurishravas, Shalya and Bhagadatta occupy the right wing.',points:['Ashvatthama, Somadatta and the Avanti princes occupy the left wing.','Duryodhana and the Trigartas occupy the middle; Alambusha and Shrutayush the rear.','Ganguli tentatively interprets the form as a square facing all directions. The schematic follows that interpretation, not a precise plan.'],lesson:'Modern analogy: review a responsibility from several directions instead of protecting only the most visible one.'},
{id:'padma',name:'Padma-vyuha',sa:'पद्मव्यूह',shape:'Lotus-shaped inner array',diagram:'lotus',sides:['Kaurava'],...commonArray,text:'Drona places a lotus-shaped array behind his combined cart-and-circle formation while protecting Jayadratha. Inside the lotus lies a dense needle array.',points:['This is a component of a larger defensive arrangement.','The passage establishes nesting: outer array, lotus, then needle.','The number of petals drawn is an illustration, not a troop count or a textual specification.'],lesson:'Modern analogy: identify the layers of a problem before trying to solve its innermost part.'},
{id:'suchi',name:'Suchi / Suchimukha',sa:'सूची · सूचीमुख',shape:'Needle / needle-mouth',diagram:'needle',sides:['Pandava','Kaurava'],...formationPassage('Bhishma','LXXVII','06077'),text:'Warriors headed by Abhimanyu form Suchimukha and penetrate the Kaurava chariot division to support Bhima and Dhrishtadyumna.',points:['This is an actual Pandava use, separate from Yudhishthira’s earlier proposal in Bhishma §XIX.','Suchi and Suchimukha name related needle and needle-mouth forms; their deployments are not identical.'],lesson:'Modern analogy: focus a small coordinated effort on a clear immediate need.',uses:[formationUse('Kaurava','Drona','LXXXVII','07083','Drona nests a dense Suchi inside the lotus. Kritavarman stands at its mouth, followed by the Kamboja ruler and Jalasandha, then Duryodhana and Karna. Jayadratha is stationed behind them at one side of the needle.')]},
{id:'composite',name:'Shakata–Chakra array',sa:'शकट · चक्र · पद्म · सूची',shape:'Drona’s composite array',diagram:'composite',sides:['Kaurava'],...commonArray,text:'For Jayadratha’s protection, Drona combines a cart-shaped and circular array, with a lotus behind it and a needle within the lotus. These are linked parts of one deployment.',points:['Drona stands at the cart’s entrance.','Kritavarman guards the needle’s mouth; further forces stand between the entrance and Jayadratha.','The diagram shows only the order of these layers, without converting epic dimensions into a verified battlefield map.'],lesson:'Modern analogy: plan how several layers of support connect; merely adding more layers does not explain their coordination.'},
{id:'madhyama',name:'Madhyama array',sa:'मध्यम',shape:'Named form; outline unstated',diagram:'unspecified',sides:['Pandava'],...formationPassage('Shalya','18','09018'),text:'After Shalya’s death, his followers attack the Pandavas. The Pandavas meet the united attack in the formation called Madhyama.',points:['The surrounding episode describes Pandava leaders rallying around Yudhishthira.','The translation names Madhyama but supplies no geometric outline.','A shape is therefore not reconstructed here.'],lesson:'Modern analogy: rally around the person carrying a shared responsibility when support is needed.'},
{id:'allfacing',name:'All-facing opening array',sa:'सर्वतोमुख · वर्णन',shape:'Described deployment',diagram:'square',sides:['Kaurava'],...formationPassage('Bhishma','XVII','06017'),text:'The opening Kaurava deployment is described with elephants as its body, kings as its head, horses as its wings and its face turned towards all sides.',points:['This is the all-facing description often associated with the name Sarvatomukha.','Ganguli describes its orientation here without formally naming a “Sarvatomukha-vyuha”.','It should not be silently merged with the later named Sarvatobhadra.'],lesson:'Modern analogy: maintain awareness of the whole situation, including what lies outside your immediate task.'},
{id:'ocean',name:'Ocean-like array',sa:'ऊर्मि · वर्णन',shape:'Described deployment',diagram:'waves',sides:['Kaurava'],...formationPassage('Bhishma','LXXXVIII','06088'),text:'Bhishma and Drona prepare an army likened to an ocean, with horses and elephants as its waves and current. Bhishma advances first, followed by Drona and successive contingents.',points:['The account then places Bhagadatta, Brihadbala, the Trigartas, Ashvatthama, Duryodhana and Kripa in sequence.','Often discussed under “Urmi” (wave); the cited translation uses an ocean comparison rather than declaring that formal name.','The Pandava response is Shringataka.'],lesson:'Modern analogy: coordinate successive efforts so each group understands the work ahead of it.'},
{id:'asura-styles',name:'Asura, Pishacha & Rakshasa',sa:'असुर · पिशाच · राक्षस',shape:'Styles mentioned in the text',diagram:'unspecified',sides:['Kaurava'],...formationPassage('Bhishma','CIX','06109'),text:'Sanjaya says that Bhishma, on successive days, arranged forces in the manner of the Asuras, Pishachas and Rakshasas.',points:['The passage names these three styles but does not draw or explain their geometries.','Its wording does not assign one particular style to each specific day.','No invented shape or day-by-day allocation is added here.'],lesson:'Modern analogy: a label is not enough to understand a plan; ask what it actually requires.'},
{id:'shikhandin-front',name:'Shikhandin in the van',sa:'शिखण्डी अग्रभागे',shape:'Described deployment',diagram:'front',sides:['Pandava'],...formationPassage('Bhishma','CIX','06109'),text:'The Pandavas place Shikhandin at the front, with Bhima and Arjuna protecting the wheels of his chariot. Other leaders support the advance.',points:['This deployment is central to the approach against Bhishma.','The cited section gives positions without naming a “Surya” or “Deva” formation.','Roles and Bhishma’s stated constraint matter more here than an inferred geometric outline.'],lesson:'Modern analogy: understand the constraints and responsibilities on which a plan depends.'},
{id:'karna-wings',name:'Karna’s wings & counter-array',sa:'पक्ष · प्रतिव्यूह',shape:'Described deployments',diagram:'wings',sides:['Kaurava','Pandava'],...formationPassage('Karna','46','08046'),text:'Sanjaya describes Karna’s army through its wings and further wings. Arjuna then arranges the Pandava counter-array with Dhrishtadyumna at its head.',points:['Kripa, the Magadhas and Kritavarman are placed in the Kaurava right wing; Shakuni and Uluka guard farther to that side.','Yudhishthira assigns opponents, including Arjuna against Karna and Bhima against Duryodhana.','This section supplies a deployment and assignments, not a named geometric vyuha.'],lesson:'Modern analogy: assign responsibilities explicitly, then coordinate them across the wider group.'},
{id:'shalya-arrays',name:'Shalya & the three divisions',sa:'शल्य · त्रिविध सेना',shape:'Final-day deployments',diagram:'divisions',sides:['Kaurava','Pandava'],...formationPassage('Shalya','8','09008'),text:'Shalya leads the Kaurava array, described as auspicious in every respect. The Pandavas divide their army into three bodies to confront the remaining Kaurava force.',points:['Kritavarman holds the Kaurava left, Kripa the right, Ashvatthama the rear and Duryodhana the centre.','Yudhishthira confronts Shalya; Arjuna is assigned Kritavarman and the Samsaptakas; Bhima, Kripa; the twins, Shakuni and Uluka.','Ganguli uses descriptive wording here. It should not be treated as a new, precisely mapped geometric shape.'],lesson:'Modern analogy: reassess your organization when circumstances and available support change.'}
);
let formationSide='All';
function visibleFormations(){return FORMATIONS.filter(f=>formationSide==='All'||f.sides.includes(formationSide));}
function formationBrowser(f){const visible=visibleFormations();return `<div class="formation-filter"><div class="segmented" aria-label="Army using the formation">${['All','Pandava','Kaurava'].map(s=>`<button data-formation-side="${s}" class="${formationSide===s?'selected':''}" aria-pressed="${formationSide===s}">${s==='All'?'Both armies':s+' side'}</button>`).join('')}</div><span class="fine-print" role="status">${visible.length} of ${FORMATIONS.length} studies · named forms &amp; described deployments</span></div><div class="formation-tabs" aria-label="Choose a formation">${visible.map(x=>`<button class="formation-tab ${x.id===f.id?'selected':''}" data-formation="${x.id}" aria-pressed="${x.id===f.id}"><span lang="sa">${x.sa}</span><b>${x.name}</b><small>${x.shape}</small><small class="formation-army">${x.sides.join(' & ')} · ${x.diagram==='unspecified'?'text account':'study'}</small></button>`).join('')}</div>`;}
function formationOccurrences(f){return `<p class="formation-side-label">${f.sides.join(' & ')} side${f.sides.length>1?'s':''}</p>${f.uses?.length?`<div class="formation-uses"><h3>Other documented uses</h3>${f.uses.map(u=>`<section><span class="small-label">${u.side.toUpperCase()} SIDE</span><p>${u.text}</p>${sourceLink(u.url,u.source)}</section>`).join('')}</div>`:''}`;}
function drawStudyFormation(f){
  if(f.diagram==='unspecified')return `<div class="formation-text-diagram"><span lang="sa">व्यूह</span><h3>The name survives.<br>The outline is not supplied.</h3><p>Read the cited passage and the documented roles. This study leaves the geometry open.</p></div>`;
  let marks='',guides='';const dot=(x,y)=>marks+=`<circle cx="${x}" cy="${y}" r="6" class="troop a"/>`;const label=(x,y,t)=>`<text x="${x}" y="${y}" text-anchor="middle">${t}</text>`;const path=d=>guides+=`<path d="${d}" fill="none" stroke="currentColor" opacity=".25"/>`;const row=(y,a=100,b=360)=>{for(let x=a;x<=b;x+=26)dot(x,y)};let caption='Illustration of the named form';
  if(f.diagram==='crescent'){for(let j=0;j<2;j++)for(let i=0;i<=18;i++){let a=i*Math.PI/18;dot(230+Math.cos(a)*(155-j*27),115+Math.sin(a)*(175-j*27))}guides+=label(230,340,'Horns · middle · supporting forces');}
  if(f.diagram==='circle'){for(const r of [60,110,155])for(let i=0;i<20;i++){let a=i*Math.PI/10;dot(230+Math.cos(a)*r,205+Math.sin(a)*r)}guides+=label(230,210,'Mandala');}
  if(f.diagram==='square'){for(let y=85;y<=325;y+=30)for(let x=110;x<=350;x+=30)if(x===110||x===350||y===85||y===325)dot(x,y);guides+=label(230,45,'Front')+label(230,210,'Centre')+label(230,365,'Rear');caption='Orientation schematic · not a measured plan';}
  if(f.diagram==='wedge'||f.diagram==='needle'){for(let y=70;y<=320;y+=30){const half=f.diagram==='needle'?(y-40)*.16:(y-40)*.43;for(let x=230-half;x<=230+half;x+=22)dot(x,y)}guides+=label(230,40,'Leading point')+label(230,365,'Supporting ranks');caption=f.diagram==='wedge'?'Symbolic Vajra study · geometry not specified':caption;}
  if(['hawk','makara','horns','wings'].includes(f.diagram)){for(let y=80;y<=310;y+=28)dot(230,y);for(let i=1;i<=6;i++){let y=f.diagram==='horns'?220-i*23:170+i*16;dot(230-i*25,y);dot(230+i*25,y);if(f.diagram==='makara'){dot(230-i*18,290+i*9);dot(230+i*18,290+i*9)}}guides+=label(230,45,f.diagram==='horns'?'Two horns':'Front')+label(230,360,'Rear support');}
  if(f.diagram==='lotus'){for(let p=0;p<8;p++){const a=p*Math.PI/4;for(let i=0;i<9;i++){let t=i*Math.PI*2/9;const along=85+65*Math.cos(t),across=27*Math.sin(t);dot(230+Math.cos(a)*along-Math.sin(a)*across,205+Math.sin(a)*along+Math.cos(a)*across)}}guides+=label(230,210,'Needle within');}
  if(f.diagram==='waves'){for(let y=90;y<=310;y+=55)for(let x=80;x<=380;x+=25)dot(x,y+17*Math.sin(x/48));guides+=label(230,370,'Successive contingents');caption='Ocean comparison · illustrative waves';}
  if(f.diagram==='front'){dot(230,80);dot(150,120);dot(310,120);row(210);row(245);row(280);guides+=label(230,45,'Shikhandin')+label(150,155,'Bhima')+label(310,155,'Arjuna')+label(230,340,'Supporting forces');}
  if(f.diagram==='composite'){[['Cart / circle',70],['Lotus',170],['Needle within lotus',270]].forEach(([t,y],i)=>{guides+=`<rect x="${90+i*15}" y="${y-20}" width="${280-i*30}" height="65" rx="3" fill="none" stroke="currentColor" opacity=".4"/>`+label(230,y+19,t);if(i<2)path(`M230 ${y+45}v35`)});caption='Relationship between layers · not troop positions';}
  if(f.diagram==='divisions'){for(let c=0;c<3;c++){for(let y=130;y<=250;y+=30)for(let x=80+c*120;x<135+c*120;x+=24)dot(x,y);guides+=label(105+c*120,300,`Division ${c+1}`)}caption='Pandava three-body division · schematic only';}
  return `<svg class="formation-svg" viewBox="0 0 460 435" role="img" aria-label="${esc(f.name)}: illustrative teaching schematic, not an exact reconstruction">${guides}${marks}${label(230,410,caption)}</svg>`;
}
